/* Mobile navigation shares the desktop records, filters and local account flows. */
let mobileMapMode='map',mobileDetailReturn='#/map',mobileLastRoute='',mobileLocationLevel=0;
function isMobileView(){return !!window.matchMedia?.('(max-width: 760px)').matches}
const MOBILE_NAV=[['','house','Нүүр'],['favorites','heart','Сонирхсон'],['map','pin','Газрын зураг'],['sale','apartment','Шинэ төсөл'],['more','menu','Миний булан']];
function mobileNavMarkup(route){const selected=['room','offices'].includes(route)?'map':['my','listing','login','faq','inquiry','notice','terms','privacy','agent'].includes(route)?'more':route;return MOBILE_NAV.map(([path,glyph,label])=>`<a href="#/${path}" ${path==='favorites'?'onclick="favTab=1"':''} ${selected===path?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span></a>`).join('')}
function mobileHeaderMarkup(route){if(!route)return `<a class="mobile-brand" href="#/" aria-label="Нүүр хуудас"><img src="assets/oroo.png" alt="Өрөө"></a><div><a href="#/search" aria-label="Хайх">${icon('search')}</a><a href="#/notice" aria-label="Мэдээ, мэдээлэл">${icon('bell')}</a></div>`;const titles={favorites:'Сонирхсон',sale:'Шинэ төсөл',more:'Миний булан',my:'Миний булан',listing:'Зар нэмэх',search:'Байршил хайх',login:'Нэвтрэх',community:'Манай хороолол',faq:'Тусламж',inquiry:'Холбоо барих',notice:'Мэдээ, мэдээлэл',complex:'Хотхоны мэдээлэл',complexes:'Хотхонууд',article:'Зөвлөгөө',privacy:'Нууцлал',terms:'Үйлчилгээний нөхцөл',agent:'Агентын үйлчилгээ',offices:'Зуучлалын байгууллага'};return `<button type="button" onclick="mobileBack()" aria-label="Буцах">${icon('chevron-left')}</button><b>${titles[route]||'Өрөө'}</b><a href="#/search" aria-label="Хайх">${icon('search')}</a>`}
function mobileBack(){const route=(location.hash||'#/').slice(2).split('/')[0];if(route==='offices'){location.hash=officeReturnListing?'#/room/'+officeReturnListing:'#/map';return}if(route==='room'){location.hash=mobileDetailReturn.startsWith('#/')&&!mobileDetailReturn.startsWith('#/room/')?mobileDetailReturn:'#/map';return}location.hash=['my','listing','login','faq','inquiry','notice','privacy','terms','agent'].includes(route)?'/more':'/'}
function mobileHomeExtras(){return `<div class="mobile-home-extras"><div class="mobile-quick-links"><a href="#/favorites" onclick="favTab=1">${icon('heart')}<span>Сонирхсон</span></a><a href="#/listing/new">${icon('plus')}<span>Зар нэмэх</span></a><a href="#/faq">${icon('help-circle')}<span>Тусламж</span></a></div><a class="mobile-guide-banner" href="#/article/1"><div><span>ӨРӨӨ · ТАНЫ ОРОН ЗАЙ</span><b>Зөв байр. Зөв сонголт.</b><p>Нүүхээс өмнө шалгах зүйлс</p></div><div class="mobile-guide-symbol">${icon('house')}${icon('check')}</div>${icon('chevron-right')}</a></div>`}
function mobileSearchPage(){return `<div class="wrap mobile-search-page">${searchbar()}<section><div class="section-head"><h2>Хаана байр хайж байна вэ?</h2></div><p class="muted">Дүүрэг, хотхон эсвэл зарын дугаараар хайгаарай.</p><div class="mobile-districts">${areas.map(area=>`<button data-value="${esc(area)}" onclick="chooseSearch(this)">${icon('pin')}<span>${esc(area)}</span>${icon('chevron-right')}</button>`).join('')}</div></section>${flowState.searches.length?`<section><h2>Сүүлд хайсан</h2>${flowState.searches.slice(0,5).map(value=>`<button class="mobile-recent-query" data-value="${esc(value)}" onclick="chooseSearch(this)">${icon('clock')}<span>${esc(value)}</span>${icon('arrow-up-right')}</button>`).join('')}</section>`:''}</div>`}
function mobileMenuGroup(title,items){return `<section class="mobile-menu-group"><h2>${title}</h2>${items.map(([url,glyph,label,count])=>`<a href="#/${url}">${icon(glyph)}<span>${label}</span>${count!==undefined?`<b>${count}</b>`:''}${icon('chevron-right')}</a>`).join('')}</section>`}
function mobileMorePage(){return `<div class="wrap mobile-more-page"><section class="mobile-profile"><div class="mobile-avatar">${icon('user')}</div><div><span>${flowState.profile.demo?'Демо бүртгэл':'ӨРӨӨ-Д ТАВТАЙ МОРИЛ!'}</span><h1>${flowState.profile.demo?esc(flowState.profile.name):'Таны орон зай эндээс эхэлнэ'}</h1></div><a href="#/${flowState.profile.demo?'my/profile':'login'}">${flowState.profile.demo?'Мэдээлэл засах':'Нэвтрэх / Бүртгүүлэх'}${icon('chevron-right')}</a></section><div class="mobile-account-shortcuts"><a href="#/my/listings">${icon('apartment')}<b>${flowState.listings.length}</b><span>Миний зарууд</span></a><a href="#/my/messages">${icon('message')}<b>${flowState.requests.filter(r=>r.kind==='message').length}</b><span>Лавлагаа</span></a><a href="#/favorites" onclick="favTab=1">${icon('heart')}<b>${saved.length}</b><span>Сонирхсон</span></a></div><a class="mobile-add-listing" href="#/listing/new">${icon('plus')}<div><b>Зар нэмэх</b><span>Өөрийн орон зайг бусадтай хуваалцаарай</span></div>${icon('chevron-right')}</a>${mobileMenuGroup('Миний үйл ажиллагаа',[['my/listings','apartment','Миний зарууд'],['my/messages','message','Зарын лавлагаа'],['my/phone','phone','Утасны лавлагаа'],['my/stories','file-text','Миний түүх'],['my/profile','user-circle','Миний мэдээлэл']])}${mobileMenuGroup('Өрөөтэй хамт',[['community','users','Манай хороолол'],['complexes','apartment','Хотхонууд'],['faq','help-circle','Тусламж'],['inquiry','message','1:1 лавлагаа'],['notice','bell','Мэдээ, мэдээлэл'],['pro','briefcase','Өрөө PRO · Ажлын самбар'],['offices','briefcase','Зуучлалын байгууллагууд'],['agent','briefcase','Агентын үйлчилгээ']])}${mobileMenuGroup('Үйлчилгээний мэдээлэл',[['terms','file-text','Үйлчилгээний нөхцөл'],['privacy','shield','Нууцлалын мэдээлэл']])}<p class="mobile-version">Өрөө · Монголын үл хөдлөх хөрөнгө<br>Туршилтын хувилбар · Мэдээлэл энэ браузерт хадгалагдана.</p></div>`}
function mobileMapCategoryMarkup(){return `<button class="mobile-map-category" type="button" onclick="openMobileCategories()" aria-label="Зарын төрөл сонгох">${categoryIcon(category)}<span>${['Орон сууц','Хаус','Оффис','Газар','Богино түрээс'][category]||'Бүх зар'}</span></button>`}
function openMobileCategories(){modal(`<h2>Зарын төрөл</h2><div class="mobile-category-choices"><button onclick="category=-1;activeDetail=null;goFlow('map')" ${category===-1?'aria-current="true"':''}>${icon('map')}<span>Бүх зар</span>${icon('chevron-right')}</button>${types.map((label,i)=>`<button onclick="category=${i};activeDetail=null;goFlow('map/${i}')" ${category===i?'aria-current="true"':''}>${categoryIcon(i)}<span>${label}</span>${icon('chevron-right')}</button>`).join('')}</div>`)}
function mobileMapControlsMarkup(){return `<button class="mobile-map-toggle" type="button" onclick="setMobileMapMode(mobileMapMode==='map'?'list':'map')"></button>`}
function mobileLocationTabs(){return `<div class="mobile-location-tabs" aria-label="Байршлын шат">${['Хот / Аймаг','Дүүрэг','Хороо'].map((label,i)=>`<button type="button" onclick="setMobileLocationLevel(${i})" ${mobileLocationLevel===i?'aria-current="step"':''} ${i>0&&locationProvince!=='Улаанбаатар'?'disabled':''}><span>${i+1}</span>${label}</button>`).join('')}</div><p class="mobile-location-context">${esc(mobileLocationLevel===0?'Хот / аймгаа сонгоно уу':mobileLocationLevel===1?locationProvince:locationProvince+' · '+locationDistrict)}</p>`}
function setMobileLocationLevel(level){mobileLocationLevel=level;renderLocationPicker()}
function syncMobileMapControls(){document.body.classList.toggle('mobile-list-view',mobileMapMode==='list');const button=document.querySelector('.mobile-map-toggle');if(button){button.innerHTML=icon(mobileMapMode==='map'?'list':'map')+'<span>'+(mobileMapMode==='map'?'Жагсаалт · '+filtered().length:'Газрын зураг')+'</span>';button.setAttribute('aria-label',mobileMapMode==='map'?'Зарын жагсаалт харах':'Газрын зураг харах');button.setAttribute('aria-pressed',String(mobileMapMode==='list'))}}
function setMobileMapMode(mode){mobileMapMode=mode==='list'?'list':'map';syncMobileMapControls();propertyMap?.resize()}
function mobilePropertyPage(id){const h=homes.find(item=>item.id===id&&isPublicListing(item));if(!h)return `<div class="wrap">${emptyFlow('Зар олдсонгүй','Хайлтаас өөр зар сонгоно уу.','<a href="#/map">Зарууд харах</a>')}</div>`;return `<div class="mobile-room-host"><aside class="detail-column">${listingDetailMarkup(h)}</aside></div>`}
function mountMobileProperty(id){const h=homes.find(item=>item.id===id&&isPublicListing(item)),column=document.querySelector('.mobile-room-host .detail-column');if(!h||!column)return;recent=[id,...recent.filter(n=>n!==id)].slice(0,50);localStorage.setItem('mn-recent',JSON.stringify(recent));column.append(column.querySelector('.detail-actions'));bindDetailNavigation(column);const close=column.querySelector('.detail-head-actions button:last-child');if(close){close.innerHTML=icon('chevron-left');close.setAttribute('aria-label','Буцах')}activeDetail=null}
function mountMobileApp(route){const header=document.getElementById('mobile-app-header'),nav=document.getElementById('mobile-bottom-nav');if(header)header.innerHTML=mobileHeaderMarkup(route);if(nav)nav.innerHTML=mobileNavMarkup(route);if(document.body.dataset)document.body.dataset.mobileRoute=route||'home';document.body.classList.toggle('mobile-room-page',route==='room'&&isMobileView());syncMobileMapControls();if(location.hash!==mobileLastRoute){if(mobileLastRoute&&!mobileLastRoute.startsWith('#/room/'))mobileDetailReturn=mobileLastRoute;mobileLastRoute=location.hash}}
window.matchMedia?.('(max-width: 760px)').addEventListener?.('change',()=>{const form=document.querySelector('#listing-editor-form');if(form){captureListingDraft(form);persistListingDraft()}const openId=activeDetail;activeDetail=null;if(isMobileView()&&openId&&!location.hash.startsWith('#/room/')){mobileDetailReturn=location.hash;location.hash='/room/'+openId;return}render()});
